<?php
$dir=sys_get_temp_dir().'/revista-cms-'.bin2hex(random_bytes(6)); mkdir($dir,0700); putenv('RSS_DATA_DIR='.$dir); putenv('REVISTA_CONFIG_DIR='.$dir);
require dirname(__DIR__).'/cms/core.php'; $count=0;
function cms_check($ok,$message) { global $count; if(!$ok) throw new RuntimeException($message); $count++; }
$db=cms_db(); cms_check((int)$db->query('SELECT count(*) FROM cms_sections')->fetchColumn()===5,'Cinco seções iniciais');
cms_check($db->query('SELECT category FROM cms_sections ORDER BY position')->fetchAll(PDO::FETCH_COLUMN)===['ponta-grossa','viagem','lazer','gastronomia','esporte'],'Ordem solicitada');
cms_save_section(1,['title'=>'Cidade','category'=>'Ponta Grossa','color'=>'#112233','position'=>1,'active'=>1]);
cms_check($db->query('SELECT color FROM cms_sections WHERE id=1')->fetchColumn()==='#112233','Cor configurável validada');
$rejected=false; try {cms_save_section(0,['title'=>'X','category'=>'x','color'=>'red;display:none','position'=>0]);} catch(InvalidArgumentException $e) {$rejected=true;} cms_check($rejected,'Bloquear CSS arbitrário');
cms_save_section(0,['title'=>'Nova','category'=>'Nova Categoria','color'=>'#223344','position'=>6,'active'=>1]); cms_check(in_array('nova-categoria',cms_categories(),true),'Novas categorias disponíveis');
cms_save_banner(0,['section_id'=>1,'title'=>'Promoção','image'=>'https://example.com/banner.png','link'=>'https://example.com','active'=>1]);
cms_check((int)$db->query('SELECT count(*) FROM cms_banners WHERE active=1')->fetchColumn()===1,'Banner ativado');
cms_save_banner(1,['section_id'=>1,'title'=>'Promoção','image'=>'https://example.com/banner.png','link'=>'https://example.com']); cms_check((int)$db->query('SELECT active FROM cms_banners')->fetchColumn()===0,'Desativar banner');
$values=['title'=>'Notícia manual','category'=>'Ponta Grossa','image'=>'https://example.com/photo.png','body'=>'Texto completo']; cms_save_news(0,0,$values);
$before=cms_news_entries(); cms_check(count($before)===1 && $before[0]['kind']==='cms','Cadastro manual disponível');
$seq=$before[0]['order']['seq']; $values['title']='Notícia editada'; cms_save_news(1,0,$values);
cms_check(cms_news_entries()[0]['title']==='Notícia editada' && cms_news_entries()[0]['order']['seq']===$seq,'Editar mantém ordem de cadastro');
$legacy=[['id'=>45,'titulo'=>'Antiga SQL','categoria'=>'ponta grossa','foto1'=>'https://example.com/old.png','conteudo'=>'Antiga','created_at'=>'2020-01-01']];
$entries=cms_news_entries('ponta-grossa',$legacy); cms_check(count($entries)===2 && $entries[0]['kind']==='cms' && $entries[1]['kind']==='sql','SQL e manual misturados por cadastro');
$db->prepare("UPDATE content_order SET registered_at='2026-01-01 10:00:00' WHERE kind='cms'")->execute();
$db->prepare("UPDATE content_order SET registered_at='2026-01-01 10:00:30' WHERE kind='sql'")->execute();
rss_save_source(0,'RSS','https://example.com/rss','ponta-grossa');
$png=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jX1sAAAAASUVORK5CYII=');
$photo=rss_cache_image('https://example.com/rss.png',fn($url,$limit)=>[$png,$url]);
rss_store($db,1,[['identity'=>'rss-1','title'=>'Do RSS','url'=>'https://example.com/rss-1','summary'=>'Resumo','body'=>'Texto','image'=>'https://example.com/rss.png','image_file'=>$photo,'published_at'=>'2020-01-01 00:00:00']]);
$db->exec("UPDATE content_order SET registered_at='2026-01-01 10:00:15' WHERE kind='rss'");
$merged=cms_news_entries('ponta-grossa',$legacy);
cms_check(array_column($merged,'kind')===['sql','rss','cms'],'Ordem de cadastro comum intercala SQL, RSS e manual');
$db->exec('DELETE FROM sources');
cms_delete_news(0,45); cms_check(count(cms_news_entries('ponta-grossa',$legacy))===1,'Excluir legado do site sem destruir a tabela original');
cms_delete_news(1); cms_check(count(cms_news_entries())===0,'Apagar notícia local');
$company=['nome'=>'Hotel Teste','url'=>'hotel-teste','categoria'=>'hospedagem','perfil'=>'https://example.com/logo.png','whatsapp'=>'(42) 99999-1234','local'=>'Rua Central','telefone'=>'42 3000-0000','descritivo'=>'Hospedagem'];
cms_save_company(0,'',$company); $store=cms_companies()['rows'][0]; cms_check($store['url']==='hotel-teste','Cadastro de empresa');
cms_check(cms_whatsapp($store['whatsapp'])==='https://wa.me/5542999991234','WhatsApp com DDD'); cms_check(cms_whatsapp('')==='','WhatsApp opcional');
cms_company_views($store['_key'],true); cms_company_views($store['_key'],true); cms_check(cms_company_views($store['_key'])===2,'Contador independente por empresa');
$company['nome']='Hotel Editado'; cms_save_company($store['_id'],'',$company); cms_check(cms_companies()['rows'][0]['nome']==='Hotel Editado','Editar empresa');
$blocked=false; try {cms_save_company(0,'',$company);} catch(InvalidArgumentException $e) {$blocked=true;} cms_check($blocked,'Não duplicar endereço de empresa');
cms_delete_company($store['_id']); cms_check(cms_companies()['rows']===[],'Excluir empresa');
$blocked=false; try {cms_asset('javascript:alert(1)');} catch(InvalidArgumentException $e) {$blocked=true;} cms_check($blocked,'Bloquear URL executável');
$db->exec('DELETE FROM cms_sections WHERE id=1'); cms_check((int)$db->query('SELECT count(*) FROM cms_banners')->fetchColumn()===0,'Excluir seção remove banners vinculados');
foreach(glob($dir.'/images/*') as $file) unlink($file); if(is_dir($dir.'/images')) rmdir($dir.'/images');
foreach(glob($dir.'/*') as $file) unlink($file); rmdir($dir); echo "$count verificações do CMS passaram.\n";
